package provider

import (
	"context"
	"fmt"

	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/types"

	"github.com/intutic/terraform-provider-intutic/internal/client"
)

// Webhook signing secrets are generated by the API and returned once, so
// Terraform cannot rotate one by setting a new value. It rotates on a change
// to an arbitrary map instead, the convention hashicorp/random (`keepers`) and
// hashicorp/time (`triggers`) use: tie the map to a time_rotating resource and
// the secret is replaced on its schedule, in place, keeping the resource's id.

// secretRotationTriggersAttribute is the `secret_rotation_triggers` attribute
// of a resource whose webhook signing secret the API can replace.
func secretRotationTriggersAttribute(webhook string) schema.MapAttribute {
	return schema.MapAttribute{
		ElementType: types.StringType,
		Optional:    true,
		Description: "Arbitrary values that rotate the signing secret when they change. Changing, adding or " +
			"removing any value replaces " + webhook + "'s signing secret in place on the next apply and stores " +
			"the new one in `signing_secret`; the old secret stops working at once. Creating the resource does " +
			"not rotate, since the API issues a secret then. Only for " + webhook + ".",
	}
}

// rotationDue reports whether the planned triggers differ from the ones in
// state. An unknown value counts as a change: at plan time that is a
// time_rotating that is about to roll over.
func rotationDue(plan, state types.Map) bool { return !plan.Equal(state) }

// rotateSigningSecret asks the API for a new signing secret. The response is
// the only place the new secret ever appears.
func rotateSigningSecret(ctx context.Context, c *client.Client, path string) (string, error) {
	var out struct {
		SigningSecret string `json:"signingSecret"`
	}
	if err := c.Post(ctx, path, nil, &out); err != nil {
		return "", err
	}
	if out.SigningSecret == "" {
		return "", fmt.Errorf("POST %s returned no signingSecret", path)
	}
	return out.SigningSecret, nil
}
